const long long MOD = 1e9 + 7, BASE = 31;
const int maxn = 2e5 + 5;

int a[maxn];
int ha[maxn];
int pow1[maxn];
int cand[maxn];
int up[maxn][20];
int cnt[maxn][20];

int gethash(int l, int r) {
    int h = (ha[r] - 1LL * ha[l - 1] * pow1[r - l + 1]) % MOD;
    if (h < 0) h += MOD;
    return h;
}

int n, m;

int comp(int i, int j, int len) {
    int l = 0, r = len, res = 0;
    while (l <= r) {
        int mid = (l + r) / 2;
        if (gethash(i, i + mid) == gethash(j, j + mid)) {
            res = mid + 1;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    if (a[i + res] == a[j + res]) return 0;
    return a[i + res] < a[j + res] ? -1 : 1;
}

int x_req;
int len;

bool check(int tar) {
    for (int i = 1; i <= n; i++) {
        bool cmp = comp(i, tar, len) <= 0;
        up[i][0] = (i + len - 1 - (!cmp)) % n + 1;
        cnt[i][0] = cmp;
    }
    for (int j = 1; j < 20; j++) {
        for (int i = 1; i <= n; i++) {
            up[i][j] = up[up[i][j - 1]][j - 1];
            cnt[i][j] = cnt[i][j - 1] + cnt[up[i][j - 1]][j - 1];
        }
    }
    for (int i = 1; i <= n; i++) {
        int cur = i;
        int sum = 0;
        for (int j = 19; j >= 0; j--) {
            if ((m >> j) & 1) {
                sum += cnt[cur][j];
                cur = up[cur][j];
            }
        }
        if (sum >= x_req) return true;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    pow1[0] = 1;
    for (int i = 1; i < maxn; i++) {
        pow1[i] = (1LL * pow1[i - 1] * BASE) % MOD;
    }

    len = (n + m - 1) / m;
    for (int i = 1; i <= n; i++) {
        char c;
        cin >> c;
        a[i] = c - '0';
        a[i + n] = a[i];
    }

    x_req = n - m * (len - 1);

    n *= 2;
    for (int i = 1; i <= n; i++) {
        ha[i] = (1LL * ha[i - 1] * BASE + a[i]) % MOD;
    }
    n /= 2;

    for (int i = 1; i <= n; i++) {
        cand[i] = i;
    }

    sort(cand + 1, cand + n + 1, [](int i, int j) {
        return comp(i, j, n) < 0;
    });

    pair<int, int> ans = {1, 1};
    int l = 1, r = n;
    while (l <= r) {
        int mid = (l + r) / 2;
        if (check(cand[mid])) {
            ans = {cand[mid], cand[mid] + len - 1};
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }

    for (int i = ans.first; i <= ans.second; i++) {
        cout << a[i];
    }
}